ProjectALife.MapZones = Zones

function Zones.each(kind, fn)
    local chunks = Zones[kind]
    if type(chunks) ~= "table" or type(fn) ~= "function" then return 0 end
    local walked = 0
    for _, chunk in ipairs(chunks) do
        for x, y, w, h in string.gmatch(chunk, "(%-?%d+),(%-?%d+),(%d+),(%d+)") do
            fn({ x = tonumber(x), y = tonumber(y), w = tonumber(w), h = tonumber(h) })
            walked = walked + 1
        end
    end
    return walked
end

function Zones.list(kind)
    local result = {}
    Zones.each(kind, function(rect) result[#result + 1] = rect end)
    return result
end

return Zones
